<?php
require_once __DIR__ . '/../conexion.php';
$r=$conexion->query("SELECT matricula_al,nombre_al,apaterno_al,amaterno_al,mail_al,tel_al FROM alumnos WHERE estatus_al='BAJA' ORDER BY nombre_al");
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Alumnos de baja</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/estilos.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><a href="../index.php" class="btn btn-secondary mb-3 d-print-none">Volver al menú</a><h2>Alumnos dados de baja</h2><div class="table-responsive"><table class="table table-bordered table-striped"><thead class="table-danger"><tr><th>Matrícula</th><th>Nombre</th><th>Correo</th><th>Teléfono</th></tr></thead><tbody><?php while($f=$r->fetch_assoc()):?><tr><td><?php echo htmlspecialchars($f['matricula_al']);?></td><td><?php echo htmlspecialchars($f['nombre_al'].' '.$f['apaterno_al'].' '.$f['amaterno_al']);?></td><td><?php echo htmlspecialchars($f['mail_al']);?></td><td><?php echo htmlspecialchars($f['tel_al']);?></td></tr><?php endwhile;?></tbody></table></div><button onclick="print()" class="btn btn-primary d-print-none">Imprimir</button></main></body></html>
